from typing import List

class Solution:
    def isEulerCircuilt(self, V: int, adj: List[List[int]]) -> int:
        if V == 0:
            return 0

        degrees = [0] * V
        for i in range(V):
            degrees[i] = len(adj[i])

        odd_count = sum(1 for d in degrees if d % 2 != 0)

        if odd_count == 0:
            return 2
        elif odd_count == 2:
            return 1
        else:
            return 0
